    const tkey = `${host}:restart:${entry.then}`;
    const day = sd.fixlog.filter((f) => f.tkey === tkey && now - f.t < 24 * H);
    const held = sd.held[`${host}:${entry.then}`];
    if (!held && day.filter((f) => now - f.t < H).length < S.FIX_PER_HOUR && day.length < S.FIX_PER_DAY) {
