const input = (v) => {
  let o = parse(v);
  for (const k of ['toolParameters', 'input', 'query']) if (o && typeof o === 'object' && !o.host && o[k]) o = parse(o[k]);
  return o && typeof o === 'object' && o.host ? proposalInput(o) : null;
