  // Proxmox hosts: VMs have fixed memory (no ballooning), so RicksGarage sits near 90% by design.
  // Warn on headroom instead; host swap (SWAP_WARN_BYTES) is the real pressure signal.
  PVE_MEM_FREE_WARN_GB: 1.5,
  SWAP_WARN_BYTES: 256 * 1024 * 1024,        // Proxmox hosts
  // VMs: swap left over from a spike is harmless; pages read back in from swap mean RAM is short now.
  SWAP_IN_WARN_MB: 100,                      // per 15 minutes
  LOAD_FACTOR: 2,                            // 15-min load over this x cores = warning
  BACKUP_WARN_H: 26, BACKUP_CRIT_H: 50,
  RESTARTS_WARN: 3, RESTARTS_CRIT: 10,       // per container per hour
  RECLAIM_WARN_GB: 20,
  QUEUE_CRIT: 20,                            // stuck arr items
  STUCK_RETRY_H: 24, STUCK_BLOCKLIST_H: 48,
  // SABnzbd's temp disk is 200 GB (scratch disk, 2026-10-22); SABnzbd itself pauses at 20 GB free.
  SAB_DISK_WARN_GB: 30, SAB_DISK_CRIT_GB: 22,
  TDARR_IDLE_H: 6,                           // hours of scheduled time; the library schedule pauses 17:00-23:00 PT
  TDARR_PAUSE_HOURS: [17, 23],
  LOGIN_FAILS_CRIT: 3,                       // failed arr web logins per 15 min that email at once
  KEY_WARN_DAYS: 14, CERT_WARN_DAYS: 14,
  SCRUB_WARN_DAYS: 45,
  PVE_EXPECT_RUNNING: [110, 201, 202, 203, 204, 205],
  PVE_EXPECT_STOPPED: [113, 117],
  TZ: 'America/Los_Angeles',
  // Chat page (sysadmin.<tailnet>). CHAT_FIXES_ENABLED lets a fix proposed in chat run after Goobs
  // presses Confirm; it is separate from FIXES_ENABLED, which gates the automatic ones.
  // On since 2026-10-22 20:32Z (Goobs: "CHAT_FIXES_ENABLED on"); false = chat proposes but Confirm does nothing.
  CHAT_FIXES_ENABLED: true,
  CHAT_FIX_PER_HOUR: 2,                      // per target, counting automatic fixes too
  CHAT_FIX_PER_DAY: 10,                      // all chat fixes together
  CHAT_CONFIRM_MIN: 15,                      // a proposal expires after this
  // Telegram bot (stacks/apps/sysadmin-telegram). Pushes go to POST sysadmin-telegram:3004/notify;
  // a Telegram failure never holds up the email.
  TELEGRAM_ALERTS: true,                     // every critical email is also pushed to Telegram
  TELEGRAM_DIGEST: false,                    // the 08:00 digest is also sent to Telegram (email only when false)
};
const TB = 1e12, GB = 1e9, H = 3600e3;
const now = Date.now();
const fmtT = (ms) => new Date(ms).toLocaleString('en-US', { timeZone: SETTINGS.TZ, month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
const gb = (b) => `${(b / GB).toFixed(1)} GB`;
const tb = (b) => `${(b / TB).toFixed(2)} TB`;
const dur = (ms) => { const h = ms / H; return h < 1 ? `${Math.round(h * 60)} min` : h < 48 ? `${Math.round(h)} h` : `${Math.round(h / 24)} d`; };
const ago = (ms) => dur(now - ms);
const size = (b) => (b >= GB ? gb(b) : `${Math.round(b / 1e6)} MB`);
const ptHour = (ms) => Number(new Date(ms).toLocaleString('en-US', { timeZone: SETTINGS.TZ, hour: 'numeric', hourCycle: 'h23' }));
// One issue: key is stable across runs so the store can track first/last seen and emails.
const issue = (host, key, sev, title, detail, fix) => ({ host, key: `${host}:${key}`, sev, title, detail: detail || '', fix: fix || null });

// Telegram digest?: the 08:00 digest also goes to the Telegram bot while TELEGRAM_DIGEST is on
// (off by default: the digest is long and the email is the record). Same push as the alerts.
if (!SETTINGS.TELEGRAM_DIGEST) return [];
const TG_MAX = 12000; // characters of text; the bot splits it into several messages, the email has it all
return $input.all()
  .map((it) => it.json || {})
  .filter((j) => j.subject || j.text)
  .map((j) => {
    const text = String(j.text || '');
    return { json: {
      subject: String(j.subject || 'Homelab digest').slice(0, 200),
      text: text.length > TG_MAX ? `${text.slice(0, TG_MAX)}\n\n(cut here; the email has the rest)` : text,
    } };
  });

// Store one homelab event for the 08:00 digest. POST /webhook/homelab/<diun|kuma|scrutiny|backup|other>;
// the source is the name of the webhook node that fired (fixed paths: n8n prefixes
// paths that contain :params with the webhook id).
const sd = $getWorkflowStaticData('global');
sd.events = sd.events || [];
const q = $json.query || {};
const b = $json.body || {};
const source = $prevNode.name || 'other';
let line;
if (source === 'diun') {
  // Diun sends JSON only with the Content-Type header set (compose: DIUN_NOTIF_WEBHOOK_HEADERS_CONTENT-TYPE);
  // without it n8n hands over an empty body.
  const ctn = ((b.metadata || {}).ctn_names || '').replace(/^\//, '');
  line = b.image ? `Image update: ${b.image} (${b.status || 'new'}) on ${b.hostname || 'unknown host'}${ctn ? `, used by ${ctn}` : ''}` : `Diun sent something unreadable (Content-Type ${($json.headers || {})['content-type'] || 'missing'})`;
} else if (source === 'kuma') {
  // Kuma's own msg already starts with "[monitor] [status]"; the heartbeat's msg is the plain reason.
  const hb = b.heartbeat || {};
  const st = { 0: 'DOWN', 1: 'UP', 2: 'PENDING', 3: 'MAINTENANCE' }[hb.status] || '';
  line = `${(b.monitor && b.monitor.name) || 'monitor'} ${st}: ${hb.msg || b.msg || ''}`.trim();
} else {
  line = String(b.message || b.title || JSON.stringify(b)).replace(/\s+/g, ' ').slice(0, 300);
}
sd.events.push({ t: new Date().toISOString(), source, line });
if (sd.events.length > 500) sd.events = sd.events.slice(-500);
return [{ json: { stored: true } }];
